'use strict';

/** Default config and endpoint table for api.satoru.click. */

const DEFAULT_BASE_URL = 'https://api.satoru.click';
const DEFAULT_TIMEOUT_MS = 60000;
const DEFAULT_RETRIES = 2;
const RETRY_BASE_DELAY_MS = 800;

// Resolving an SSE progress stream can take ~25s, so it needs its own budget.
const RESOLVE_TIMEOUT_MS = 180000;

/**
 * Every platform goes through downallv2 — it covers them all.
 * The other endpoints stay reachable through `fromEndpoint()` for anyone
 * who wants to target one directly.
 */
const PRIMARY_ENDPOINT = 'downallv2';

// Which query param each endpoint expects, plus the optional extras it accepts.
const ENDPOINTS = Object.freeze({
  downallv2: { param: 'url' },
  downall: { param: 'url' },
  downallv3: { param: 'url' },
  downallv4: { param: 'url', extra: ['quality', 'music'] },
  youtubedl: { param: 'url', extra: ['format', 'base64'] },
  tikdl: { param: 'url' },
  'tiktok-video-info': { param: 'url' },
  fbdl: { param: 'url' },
  fbdlv2: { param: 'url' },
  'ig-dl': { param: 'url' },
  'instagram-download': { param: 'url' },
  xdl: { param: 'url' },
  xdlv2: { param: 'url' },
  thrdsdl: { param: 'url' },
  'threads-download': { param: 'url' },
  pindl: { param: 'url' },
  'sp-dl': { param: 'url', extra: ['quality'] },
  'soundcloud-download': { param: 'url' },
  'douyin-download': { param: 'url' },
  'bilibili-download': { param: 'url', extra: ['cookies'] },
  'capcut-download': { param: 'url' },
  'xhs-download': { param: 'url' },
  'shopee-video': { param: 'url' },
  dxvideo: { param: 'url' },
  zingmp3: { param: 'link' },
  'cdn-proxy': { param: 'url' },
});

// Used only to label results; routing does not depend on this.
const HOST_PATTERNS = Object.freeze([
  ['youtube', ['youtube.com', 'youtu.be', 'youtube-nocookie.com']],
  ['tiktok', ['tiktok.com', 'vt.tiktok.com', 'vm.tiktok.com']],
  ['facebook', ['facebook.com', 'fb.watch', 'fb.com', 'm.facebook.com']],
  ['instagram', ['instagram.com', 'instagr.am']],
  ['twitter', ['twitter.com', 'x.com', 't.co']],
  ['threads', ['threads.net', 'threads.com']],
  ['pinterest', ['pinterest.com', 'pin.it', 'pinterest.ca']],
  ['spotify', ['spotify.com', 'spoti.fi']],
  ['soundcloud', ['soundcloud.com', 'snd.sc']],
  ['douyin', ['douyin.com', 'iesdouyin.com']],
  ['bilibili', ['bilibili.com', 'b23.tv']],
  ['capcut', ['capcut.com']],
  ['xiaohongshu', ['xiaohongshu.com', 'xhslink.com']],
  ['shopee', ['shopee.vn', 'shopee.com']],
  ['zingmp3', ['zingmp3.vn']],
  ['xvideos', ['xvideos.com']],
  ['reddit', ['reddit.com', 'redd.it']],
  ['vimeo', ['vimeo.com']],
  ['twitch', ['twitch.tv']],
  ['linkedin', ['linkedin.com']],
  ['tumblr', ['tumblr.com']],
  ['weibo', ['weibo.com', 'weibo.cn']],
  ['kuaishou', ['kuaishou.com']],
]);

// The API wraps its payload under different keys depending on the endpoint.
const PAYLOAD_KEYS = Object.freeze(['data', 'answer', 'result', 'results']);

// Marker for links that stream progress events instead of bytes.
const SSE_URL_MARKER = 'sse-progress';

module.exports = {
  DEFAULT_BASE_URL,
  DEFAULT_TIMEOUT_MS,
  DEFAULT_RETRIES,
  RETRY_BASE_DELAY_MS,
  RESOLVE_TIMEOUT_MS,
  PRIMARY_ENDPOINT,
  ENDPOINTS,
  HOST_PATTERNS,
  PAYLOAD_KEYS,
  SSE_URL_MARKER,
};
